slide4.vulnerable:
function initWallet(address[] memory owners) public {
  m_owners = owners;
}
function kill(address payable to) external onlyOwner {
  selfdestruct(to);
}

slide4.corrected:
function initWallet(address[] memory owners) external initializer {
  if(m_owners.length != 0) {
    revert("already initialized");
  }
  m_owners = owners;
}
// implementation cannot selfdestruct
